/* The mellum2 pre-tokenizer and BPE against Mellum 2.1's own tokenizer
 * (tests/mellum_tokenizer_cases.inc, generated by
 * tests/gen_mellum_tokenizer_cases.py).  The pieces need no model; the ids need
 * the GGUF's vocabulary and merges and are checked when DS4_TEST_MELLUM_MODEL
 * is set.  Includes ds4.c to reach the static segmenter. */
#include "../ds4.c"

typedef struct {
    const char *text;
    int n_pieces;
    const char *piece[32];
    const int *ids;
    int n_ids;
} mellum_tokenizer_case;

#include "mellum_tokenizer_cases.inc"

#define N_CASES (sizeof(MELLUM_TOKENIZER_CASES) / sizeof(MELLUM_TOKENIZER_CASES[0]))

static int g_failures;

typedef struct {
    uint64_t len[256];
    size_t n;
    uint64_t expect_start;
    bool gap;
} collect_state;

static void collect_piece(void *ud, uint64_t start, uint64_t end) {
    collect_state *s = ud;
    if (start != s->expect_start || end <= start) s->gap = true;
    s->expect_start = end;
    if (s->n < sizeof(s->len) / sizeof(s->len[0])) s->len[s->n] = end - start;
    s->n++;
}

static void show(const char *s, size_t n, char *out, size_t cap) {
    size_t o = 0;
    for (size_t i = 0; i < n && o + 5 < cap; i++) {
        const unsigned char c = (unsigned char)s[i];
        if (c >= 0x20 && c < 0x7f) out[o++] = (char)c;
        else o += (size_t)snprintf(out + o, cap - o, "\\x%02x", c);
    }
    out[o] = '\0';
}

/* The segmenter's pieces equal the reference pre-tokenizer's, case by case. */
static void check_pieces(void) {
    int bad = 0;
    for (size_t k = 0; k < N_CASES; k++) {
        const mellum_tokenizer_case *c = &MELLUM_TOKENIZER_CASES[k];
        collect_state st;
        memset(&st, 0, sizeof(st));
        const size_t len = strlen(c->text);
        mellum_segment_pieces(c->text, len, collect_piece, &st);
        bool ok = !st.gap && st.expect_start == len && st.n == (size_t)c->n_pieces;
        uint64_t at = 0;
        for (size_t i = 0; ok && i < st.n; i++) {
            const size_t want = strlen(c->piece[i]);
            ok = st.len[i] == want && !memcmp(c->text + at, c->piece[i], want);
            at += st.len[i];
        }
        if (!ok) {
            char text[256];
            show(c->text, len, text, sizeof(text));
            fprintf(stderr, "FAIL pieces \"%s\": got %zu, want %d\n", text, st.n, c->n_pieces);
            bad++;
        }
    }
    g_failures += bad;
    printf("%s %zu cases: pieces equal the reference pre-tokenizer's\n", bad ? "FAIL" : "ok  ", N_CASES);
}

/* Bytes that are not UTF-8 must still be tiled, whatever the classes say. */
static void check_invalid_utf8(void) {
    static const char *const bad[] = {
        "\377", "a\303", "\360\237", "\200\200x", "x\342\200", "1\377 2", "\300\257",
    };
    int n_bad = 0;
    for (size_t k = 0; k < sizeof(bad) / sizeof(bad[0]); k++) {
        collect_state st;
        memset(&st, 0, sizeof(st));
        mellum_segment_pieces(bad[k], strlen(bad[k]), collect_piece, &st);
        if (st.gap || st.expect_start != strlen(bad[k])) {
            fprintf(stderr, "FAIL invalid UTF-8 case %zu does not tile\n", k);
            n_bad++;
        }
    }
    g_failures += n_bad;
    printf("%s invalid UTF-8 is tiled, never dropped\n", n_bad ? "FAIL" : "ok  ");
}

/* With the real vocabulary and merges, the ids equal the reference encode. */
static void check_ids(const char *path) {
    ds4_model m;
    model_open(&m, path, false, false);
    config_validate_model(&m);
    ds4_vocab vocab;
    vocab_load(&vocab, &m);
    int bad = 0;
    for (size_t k = 0; k < N_CASES; k++) {
        const mellum_tokenizer_case *c = &MELLUM_TOKENIZER_CASES[k];
        token_vec got = {0};
        bpe_tokenize_text(&vocab, c->text, &got);
        bool ok = got.len == c->n_ids;
        for (int i = 0; ok && i < got.len; i++) ok = got.v[i] == c->ids[i];
        if (!ok) {
            char text[256];
            show(c->text, strlen(c->text), text, sizeof(text));
            fprintf(stderr, "FAIL ids \"%s\": got %d ids [", text, got.len);
            for (int i = 0; i < got.len; i++) fprintf(stderr, "%s%d", i ? " " : "", got.v[i]);
            fprintf(stderr, "], want %d [", c->n_ids);
            for (int i = 0; i < c->n_ids; i++) fprintf(stderr, "%s%d", i ? " " : "", c->ids[i]);
            fprintf(stderr, "]\n");
            bad++;
        }
        token_vec_free(&got);
    }
    vocab_free(&vocab);
    model_close(&m);
    g_failures += bad;
    printf("%s %zu cases: ids equal the reference encode (real GGUF)\n", bad ? "FAIL" : "ok  ", N_CASES);
}

int main(void) {
    check_pieces();
    check_invalid_utf8();
    const char *model = getenv("DS4_TEST_MELLUM_MODEL");
    if (model && model[0]) check_ids(model);
    else printf("skip ids: DS4_TEST_MELLUM_MODEL unset\n");
    if (g_failures) {
        fprintf(stderr, "test-mellum-tokenizer: %d failure(s)\n", g_failures);
        return 1;
    }
    printf("test-mellum-tokenizer: ok\n");
    return 0;
}
